package org.jlinalg.cli;
import static org.jlinalg.cli.StudyPublicEvidence.*;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.jlinalg.study.StudyOperationExecutor.Context;
import org.jlinalg.study.StudyRiskScorePolicy;
import org.jlinalg.xwas.HeldOutScores;
import org.jlinalg.xwas.PredictionScores;

/** Portable complete frozen molecular score, baseline, imputation and development identity contract. */
final class StudyScoreModel {
    private StudyScoreModel() { }
    record Applied(double[] score,double[] prediction,double[] baseline,int features,String identityScope,Map<String,Object> parameters) { public Applied {parameters=Map.copyOf(parameters);} }
    static void save(Context c,Map<String,Object> p,DelimitedData input,int[] training,int[] tuning,HeldOutScores.Fit fitted)throws IOException {
        var model=new LinkedHashMap<String,Object>();model.put("format","jlinalg-held-out-score-v1");model.put("family","quantitative");model.put("feature_weights",Arrays.stream(fitted.frozen().model().weights()).boxed().toList());model.put("feature_means",Arrays.stream(fitted.frozen().featureMeans()).boxed().toList());model.put("score_intercept",fitted.frozen().model().intercept());model.put("lambda",fitted.selectedLambda());model.put("training_mean",fitted.frozen().model().trainingMean());model.put("baseline_weights",Arrays.stream(fitted.frozen().baselineWeights()).boxed().toList());
        saveSelection(c,p,model);saveModel(c,p,input,training,tuning,model);
    }
    static void save(Context c,Map<String,Object> p,DelimitedData input,int[] training,int[] tuning,org.jlinalg.xwas.BinaryPredictionScores.Fit fitted)throws IOException {
        var frozen=fitted.frozen();var model=new LinkedHashMap<String,Object>();model.put("format","jlinalg-held-out-binary-score-v1");model.put("family","binary");model.put("feature_weights",Arrays.stream(frozen.featureWeights()).boxed().toList());model.put("feature_means",Arrays.stream(frozen.featureMeans()).boxed().toList());model.put("feature_scales",Arrays.stream(frozen.featureScales()).boxed().toList());model.put("score_intercept",frozen.scoreIntercept());model.put("lambda",fitted.selectedLambda());model.put("covariate_weights",Arrays.stream(frozen.covariateWeights()).boxed().toList());model.put("baseline_weights",Arrays.stream(frozen.baselineWeights()).boxed().toList());model.put("baseline_lambda",frozen.baselineLambda());model.put("prediction_link","logit");model.put("feature_penalty","mean_log_loss_plus_elastic_net_on_training_standardized_features");model.put("covariate_penalty","positive_ridge_on_training_standardized_non_intercept_covariates");
        saveSelection(c,p,model);saveModel(c,p,input,training,tuning,model);
    }
    private static void saveSelection(Context c,Map<String,Object> p,Map<String,Object> model)throws IOException {
        if(!p.containsKey("nested_validation"))return;
        Path report=c.outputDirectory().resolve("nested-validation.yaml");var validation=StudyYaml.loadArtifact(report);
        if(!"complete".equals(validation.get("status")))throw new IllegalArgumentException("A nested frozen model requires a complete native validation report");
        model.put("model_selection",new java.util.TreeMap<>(Map.of("method","grouped_nested_cross_validation","policy",p.get("nested_validation"),"report_sha256",FollowupSupport.hash(report),"scope","native local preprocessing and penalty selection; independent external evaluation excluded")));
    }
    private static void saveModel(Context c,Map<String,Object> p,DelimitedData input,int[] training,int[] tuning,Map<String,Object> model)throws IOException {
        List<String> covariates=StudyRiskScorePolicy.list(p,"covariates"),categorical=StudyRiskScorePolicy.list(p,"categorical_covariates"),groups=StudyRiskScorePolicy.list(p,"group_columns");var levels=new LinkedHashMap<String,Object>();
        for(String cov:categorical){var values=new java.util.TreeSet<String>();for(int row:training)values.add(input.rows().get(row)[input.column(cov)]);levels.put(cov,new ArrayList<>(values));}
        // Tuning observations are development evidence even when final refit is disabled.
        int fittedRows=training.length+(Boolean.TRUE.equals(p.get("refit"))?tuning.length:0);
        int[] development=Arrays.copyOf(training,training.length+tuning.length);System.arraycopy(tuning,0,development,training.length,tuning.length);
        var ids=new ArrayList<String[]>();for(int row:development){String[] record=new String[groups.size()+1];record[0]=input.rows().get(row)[input.column(text(p.get("id_column")))];for(int i=0;i<groups.size();i++)record[i+1]=input.rows().get(row)[input.column(groups.get(i))];ids.add(record);}String identityColumn="sample_id";while(groups.contains(identityColumn))identityColumn="_"+identityColumn;var header=new ArrayList<>(List.of(identityColumn));header.addAll(groups);Path identities=c.outputDirectory().resolve("score-weights.tsv.training-ids.tsv");FollowupSupport.table(identities,header,ids);
        model.put("outcome",p.get("outcome"));model.put("features",p.get("features"));model.put("alpha",p.get("alpha"));model.put("covariates",covariates);model.put("categorical_covariates",categorical);model.put("categorical_levels",levels);model.put("missing",p.get("missing"));model.put("development_rows",fittedRows);model.put("development_identity_rows",development.length);model.put("development_identity_scope","training_and_tuning_including_model_selection_without_final_refit");model.put("training_ids",identities.getFileName().toString());model.put("training_ids_sha256",FollowupSupport.hash(identities));model.put("training_group_columns",groups);model.put("preprocessing_provenance",p.getOrDefault("preprocessing_provenance","Upstream preprocessing independence not certified"));write(c.outputDirectory().resolve("score-model.yaml"),model);
    }
    static Applied apply(Context c,Map<String,Object> p,DelimitedData input,String[] ids,String[] roles)throws IOException {
        if(!p.containsKey("model"))throw new IllegalArgumentException("Supply risk_score.model for a complete frozen JLinAlg model");Path source=c.project().resolve(text(p.get("model")));if(!Files.isRegularFile(source))throw new IllegalArgumentException("Supply the registered frozen score model");if(Files.size(source)>2097152L)throw new IllegalArgumentException("Frozen model exceeds 2-MiB metadata bound");String hash=FollowupSupport.hash(source);var model=StudyYaml.loadArtifact(source);boolean binary="jlinalg-held-out-binary-score-v1".equals(model.get("format"))&&"binary".equals(model.get("family"));if(!(binary||"jlinalg-held-out-score-v1".equals(model.get("format"))&&"quantitative".equals(model.get("family")))||!model.get("family").equals(p.get("family")))throw new IllegalArgumentException("Frozen score model format/family mismatch");
        double sourceLambda=numeric(text(model.get("lambda"))),sourceAlpha=numeric(text(model.get("alpha")));if(!Double.isFinite(sourceLambda)||sourceLambda<0||!Double.isFinite(sourceAlpha)||sourceAlpha<0||sourceAlpha>1||!java.util.Set.of("error","training_mean").contains(text(model.get("missing"))))throw new IllegalArgumentException("Invalid frozen model penalty/preprocessing contract");
        if(!text(p.get("outcome")).equals(model.get("outcome")))throw new IllegalArgumentException("Frozen model outcome identifier differs; register an explicitly appropriate model rather than relabeling its target");
        Path development=source.toAbsolutePath().getParent().resolve(text(model.get("training_ids"))).normalize();if(!development.startsWith(source.toAbsolutePath().getParent())||!Files.isRegularFile(development)||!FollowupSupport.hash(development).equals(model.get("training_ids_sha256")))throw new IllegalArgumentException("Frozen model needs its original hash-verified development identity sidecar");
        Path saved=c.outputDirectory().resolve("model-development-identities.tsv");Files.copy(development,saved);if(!FollowupSupport.hash(saved).equals(model.get("training_ids_sha256")))throw new IOException("Development identity snapshot changed");var previous=DelimitedData.read(saved);var old=new java.util.HashSet<String>();for(String[] row:previous.rows())old.add(row[0]);for(int i=0;i<ids.length;i++)if(roles[i].equals("evaluation")&&old.contains(ids[i]))throw new IllegalArgumentException("Frozen model development IDs overlap evaluation participants");
        if(model.containsKey("development_identity_rows")&&numeric(text(model.get("development_identity_rows")))!=previous.rows().size())throw new IllegalArgumentException("Frozen development identity count differs from its sealed sidecar");
        double fittedCount=model.containsKey("development_rows")?numeric(text(model.get("development_rows"))):previous.rows().size();if(!Double.isFinite(fittedCount)||fittedCount<4||fittedCount!=Math.rint(fittedCount)||fittedCount>previous.rows().size())throw new IllegalArgumentException("Invalid frozen fitted-development row count");int fittedRows=(int)fittedCount;
        String identityScope=model.containsKey("development_identity_scope")?text(model.get("development_identity_scope")):"legacy_model_selection_identity_coverage_unestablished";
        if(binary&&!identityScope.equals("training_and_tuning_including_model_selection_without_final_refit"))throw new IllegalArgumentException("Complete binary model requires its full training/tuning identity scope");
        for(String group:strings(model,"training_group_columns")){var known=new java.util.HashSet<String>();for(String[] row:previous.rows())known.add(row[previous.column(group)]);for(int i=0;i<ids.length;i++)if(roles[i].equals("evaluation")&&known.contains(input.rows().get(i)[input.column(group)]))throw new IllegalArgumentException("Frozen model development group overlaps evaluation: "+group);}
        List<String> features=strings(model,"features"),covariates=strings(model,"covariates"),categorical=strings(model,"categorical_covariates");if(features.isEmpty()||features.size()>((Number)p.get("max_features")).intValue())throw new IllegalArgumentException("Frozen model feature count exceeds bounds");
        if(covariates.contains(text(p.get("outcome")))||features.contains(text(p.get("outcome")))||features.contains(text(p.get("id_column")))||features.contains(text(p.get("partition_column"))))throw new IllegalArgumentException("Invalid frozen feature/outcome identity contract");for(Object related:list(p.get("related_phenotypes")))if(features.contains(text(map(related).get("column"))))throw new IllegalArgumentException("Related phenotype is itself a frozen score predictor");
        double[] weights=numbers(model,"feature_weights"),means=numbers(model,"feature_means"),baseWeights=numbers(model,"baseline_weights");if(weights.length!=features.size()||means.length!=features.size())throw new IllegalArgumentException("Frozen feature vectors are unaligned");var levels=map(model.get("categorical_levels"));int width=1;for(String cov:covariates)width+=categorical.contains(cov)?Math.max(0,strings(levels,cov).size()-1):1;if(baseWeights.length!=width)throw new IllegalArgumentException("Frozen baseline design width differs from its weights");
        if((long)ids.length*Math.max(features.size(),width)>20000000L)throw new IllegalArgumentException("Frozen model application exceeds dense storage bounds");double[][] x=new double[ids.length][features.size()],design=new double[ids.length][width];for(int i=0;i<ids.length;i++){design[i][0]=1;if(roles[i].equals("excluded"))continue;String[] row=input.rows().get(i);for(int j=0;j<features.size();j++){x[i][j]=numeric(row[input.column(features.get(j))]);if(Double.isNaN(x[i][j])&&!"training_mean".equals(model.get("missing")))throw new IllegalArgumentException("Missing predictor under frozen error policy");}int at=1;for(String cov:covariates){String value=row[input.column(cov)];if(categorical.contains(cov)){var categories=strings(levels,cov);if(!categories.contains(value))throw new IllegalArgumentException("Unseen category under frozen baseline: "+cov);for(int j=1;j<categories.size();j++)design[i][at++]=categories.get(j).equals(value)?1:0;}else{design[i][at]=numeric(value);if(!Double.isFinite(design[i][at++]))throw new IllegalArgumentException("Missing frozen baseline covariate");}}}
        double[] score,baseline,prediction;
        if(binary){
            if(!"logit".equals(model.get("prediction_link")))throw new IllegalArgumentException("Unsupported frozen binary prediction link");
            double[] full=numbers(model,"covariate_weights");if(full.length!=width)throw new IllegalArgumentException("Frozen full prediction design differs from its weights");
            var frozen=new org.jlinalg.xwas.BinaryPredictionScores.Frozen(weights,means,numbers(model,"feature_scales"),numeric(text(model.get("score_intercept"))),full,baseWeights,numeric(text(model.get("lambda"))),numeric(text(model.get("alpha"))),numeric(text(model.get("baseline_lambda"))),fittedRows,"training_mean".equals(model.get("missing")),null,null);
            score=frozen.score(x);baseline=frozen.baseline(design);prediction=frozen.predict(x,design);
        }else{
            var frozen=new HeldOutScores.Frozen(new PredictionScores.Model(numeric(text(model.get("score_intercept"))),weights,((Number)model.get("lambda")).doubleValue(),((Number)model.get("alpha")).doubleValue(),numeric(text(model.get("training_mean")))),means,baseWeights,fittedRows,"training_mean".equals(model.get("missing")));score=frozen.score(x);baseline=frozen.baseline(design);prediction=new double[ids.length];for(int i=0;i<ids.length;i++)prediction[i]=baseline[i]+score[i];
        }
        Path snapshot=c.outputDirectory().resolve("supplied-score-model.yaml");Files.copy(source,snapshot);if(!hash.equals(FollowupSupport.hash(source))||!hash.equals(FollowupSupport.hash(snapshot)))throw new IOException("Frozen model changed during application");var parameters=new LinkedHashMap<String,Object>();parameters.put("format",model.get("format"));parameters.put("family",model.get("family"));parameters.put("outcome",model.get("outcome"));parameters.put("lambda",sourceLambda);parameters.put("alpha",sourceAlpha);parameters.put("missing",model.get("missing"));parameters.put("features",features);parameters.put("covariates",covariates);parameters.put("categorical_covariates",categorical);parameters.put("fitted_rows",fittedRows);parameters.put("development_identity_rows",previous.rows().size());parameters.put("identity_scope",identityScope);parameters.put("source_sha256",hash);var selection=map(model.get("model_selection"));if("grouped_nested_cross_validation".equals(selection.get("method"))&&text(selection.get("report_sha256")).matches("[0-9a-f]{64}")){parameters.put("source_model_selection_method","grouped_nested_cross_validation");parameters.put("source_model_selection_report_sha256",selection.get("report_sha256"));parameters.put("source_model_selection_appraisal","source-reported frozen metadata; original cross-validation not re-executed during application");}if(binary){parameters.put("baseline_lambda",model.get("baseline_lambda"));parameters.put("prediction_link","logit");}return new Applied(score,prediction,baseline,features.size(),identityScope,parameters);
    }
    private static List<String> strings(Map<String,Object> p,String key){return list(p.get(key)).stream().map(StudyPublicEvidence::text).toList();}
    private static double[] numbers(Map<String,Object> p,String key){double[] result=list(p.get(key)).stream().mapToDouble(value->numeric(text(value))).toArray();for(double value:result)if(!Double.isFinite(value))throw new IllegalArgumentException("Nonfinite frozen model vector: "+key);return result;}
    private static double numeric(String value){if(value.isBlank()||List.of("NA","NaN",".").contains(value))return Double.NaN;double number=Double.parseDouble(value);if(!Double.isFinite(number))throw new IllegalArgumentException("Nonfinite frozen model/input value");return number;}
}
